#!/usr/bin/env node
/** Red test from a reviewer probe (workflows/dev-loop.js). Generated by Claude Code at the user's request. */
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { run, ARGS, review, finding, impl, gate } from './dev-loop.harness.mjs';

test('given an inline targeted run with a fix round, when the loop ends OK, then a full gate ran', async () => {
  // Given
  const args = { ...ARGS, inline: true, changed: ['src/Orders/OrdersQuery.cs'], verify: 'node --test x', targeted: 'node --test {files}', start: { head: 'abc1234', dirty: [] } };
  // When
  const { out, calls } = await run(args, [review([], [finding()]), review([{ id: 'F1', status: 'closed' }])], [impl({ gate: gate() })]);
  // Then
  const fulls = calls.filter(c => /^full gate/.test(c.opts.label ?? ''));
  assert.ok(out.status !== 'OK' || fulls.length > 0);
});
